target.css:
:root {
  --ink: #082b3c;
  --panel: #0e3b4d;
  --panel-deep: #082f40;
  --line: #2e6271;
  --muted: #9dc2c9;
  --aqua: #70e0d2;
  --lime: #c9ec72;
  --orange: #ffb15d;
  --cream: #eff8eb;
  --danger: #d85c54;
}

.dive-console {
  box-sizing: border-box;
  width: 500px;
  overflow: hidden;
  color: var(--cream);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.console-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--ink);
  border-bottom: 1px solid var(--line);
}

.title-block {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.kicker {
  margin: 0;
  color: var(--aqua);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

.title-block h1 {
  margin: 0;
  font-size: 21px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.4px;
}

.connection-status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--lime);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

.status-dot {
  font-size: 14px;
  line-height: 1;
}

.console-grid {
  display: grid;
  grid-template-columns: 1.35fr 0.85fr;
  gap: 12px;
  padding: 12px 16px;
}

.route-panel,
.data-panel {
  box-sizing: border-box;
  min-width: 0;
  padding: 11px;
  background: var(--panel-deep);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.route-panel {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.panel-heading h2,
.panel-heading p {
  margin: 0;
}

.panel-heading h2 {
  color: var(--cream);
  font-size: 13px;
  font-weight: 700;
}

.panel-heading p {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.6px;
}

.depth-readout {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 7px 9px;
  background: var(--panel);
  border-left: 3px solid var(--aqua);
  border-radius: 0 7px 7px 0;
}

.depth-label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.depth-value {
  color: var(--aqua);
  font-size: 27px;
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -1px;
}

.depth-unit {
  margin-left: 2px;
  color: var(--muted);
  font-size: 12px;
  letter-spacing: 0;
}

.depth-change {
  margin-left: auto;
  color: var(--lime);
  font-size: 10px;
  font-weight: 700;
}

.depth-scale,
.metric-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.scale-marker {
  display: grid;
  grid-template-columns: 35px 1fr 62px;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
}

.scale-marker b {
  color: var(--cream);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.35px;
  text-align: right;
}

.warning-marker b {
  color: var(--orange);
}

.track-line {
  height: 2px;
  background: var(--line);
  border-radius: 2px;
}

.active-line {
  background: var(--aqua);
}

.data-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.metric-list {
  gap: 0;
}

.metric {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
  border-top: 1px solid var(--line);
}

.metric-label {
  color: var(--muted);
  font-size: 11px;
}

.metric-value {
  color: var(--lime);
  font-size: 15px;
  font-weight: 700;
}

.alert-value {
  color: var(--orange);
}

.dive-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
  background: var(--ink);
  border-top: 1px solid var(--line);
}

.footer-note {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.footer-note span {
  color: var(--aqua);
  padding: 0 4px;
}

.abort-button {
  padding: 6px 10px;
  color: var(--cream);
  background: var(--danger);
  border: 1px solid var(--danger);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
}

